export type WritingMode = "sachverhalt" | "tenor" | "fälle";

export type ModeCommand = {
  id: WritingMode;
  command: string;
  title: string;
  hint: string;
};

export type Completeness = {
  complete: boolean;
  missing: Array<"handlung" | "kanal" | "betroffene" | "ziel">;
  nextQuestion: string | null;
};

export const modeCommands: ModeCommand[] = [
  {
    id: "sachverhalt",
    command: "/sachverhalt",
    title: "Sachverhalt",
    hint: "Einen neuen Verstoß beschreiben",
  },
  {
    id: "tenor",
    command: "/tenor",
    title: "Tenor",
    hint: "Einen bestehenden Tenor korrigieren",
  },
  { id: "fälle", command: "/fälle", title: "Fälle", hint: "Archiv und Hinweise durchsuchen" },
];

export function isTenor(text: string) {
  return /(zu unterlassen|wird verurteilt|ordnungsgeld|zuwiderhandlung|der beklagten wird untersagt)/i.test(
    text,
  );
}

export function inferFallgruppe(text: string) {
  const normalized = text.toLocaleLowerCase("de");
  return /klausel|agb|altvertrag/.test(normalized)
    ? "agb_klausel"
    : /cookie|consent|tracking/.test(normalized)
      ? "consent_gestaltung"
      : /dark pattern|checkout|versicherung/.test(normalized)
        ? "dark_pattern_dsa"
        : /werb|wirb|irreführ/.test(normalized)
          ? "irrefuehrende_werbung"
          : "kuendigungsbutton";
}

export function assessCompleteness(text: string): Completeness {
  const checks = {
    handlung:
      /(kündig|button|schaltfläche|klausel|cookie|consent|tracking|werb|rabatt|countdown|preis|vertrag|verlänger|versteckt|fehlt|irreführ)/i.test(
        text,
      ),
    kanal:
      /(website|webseite|app|internet|online|domain|checkout|agb|vertrag|schreiben|e-mail|social media|filiale)/i.test(
        text,
      ),
    betroffene: /(verbraucher|kund|nutzer|abonnent|betroffen|privatperson|vertragspartner)/i.test(
      text,
    ),
    ziel: /(unterlassen|künftig|soll|darf nicht|nicht mehr|muss|bereitstellen|entfernen|verbieten|untersagt)/i.test(
      text,
    ),
  };
  const missing = (Object.entries(checks) as Array<[Completeness["missing"][number], boolean]>)
    .filter(([, present]) => !present)
    .map(([name]) => name);
  const nextQuestion = !checks.handlung
    ? "Welche konkrete Handlung oder Gestaltung beanstandest du?"
    : !checks.kanal
      ? "Wo genau tritt der Verstoß auf – zum Beispiel auf einer Website, in einer App oder in einem Vertrag?"
      : !checks.betroffene
        ? "Wer ist davon betroffen – Verbraucher, Kunden oder eine andere Gruppe?"
        : !checks.ziel
          ? "Was genau soll das Unternehmen künftig unterlassen?"
          : null;
  return { complete: missing.length === 0, missing, nextQuestion };
}

export function filterModeCommands(query: string) {
  const normalized = query.toLocaleLowerCase("de");
  return modeCommands.filter((command) =>
    `${command.command} ${command.title}`.toLocaleLowerCase("de").includes(normalized),
  );
}

export function nextWrappedIndex(current: number, length: number, direction: 1 | -1) {
  if (length <= 0) return 0;
  return (current + direction + length) % length;
}

export type TenorDecision = "freigegeben" | "abgelehnt" | "weitere_pruefung";

export type TenorDraftRequest = {
  fall_id: string;
  schuldner: string;
  fundstelle: string;
  beschreibung: string;
  rechtsgrundlagen: string[];
};

export type TenorDraft = {
  fall_id: string;
  schuldner: string;
  entwurf: string;
  charakteristischer_kern: string;
  kerngleich_umfasst: string[];
  nicht_umfasst: string[];
  rechtsgrundlagen: string[];
  offene_fragen: string[];
  freigabe_durch_mensch: string | null;
};

export type TenorDraftRecord = {
  draft_id: string;
  created_at: string;
  mode: string;
  model: string;
  input: TenorDraftRequest;
  draft: TenorDraft;
  decision: TenorDecision | null;
  decided_at: string | null;
};

export type TenorProposalRequest = {
  fall_id: string;
  schuldner: string;
  fundstelle: string;
  context: string;
  fallgruppe: string;
  rechtsgrundlagen: string[];
};

export type TenorProposal = {
  strategy: "precise" | "neutral";
  title: string;
  text: string;
  source_ids: string[];
  warnings: string[];
  human_approval_required: true;
  freigabe_durch_mensch: null;
};

export type TenorProposalResponse = {
  mode: "live_openai";
  model: string;
  reference_version: string;
  proposals: [TenorProposal, TenorProposal];
};

async function requestJson<T>(url: string, init: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...init.headers,
    },
  });

  if (!response.ok) {
    let message = `HTTP ${response.status}`;
    try {
      const payload = (await response.json()) as { detail?: string | Array<{ msg?: string }> };
      if (typeof payload.detail === "string") message = payload.detail;
      else if (Array.isArray(payload.detail)) {
        message =
          payload.detail
            .map((item) => item.msg)
            .filter(Boolean)
            .join(" · ") || message;
      }
    } catch {
      // The HTTP status remains visible when the backend returns no JSON detail.
    }
    throw new Error(message);
  }

  return (await response.json()) as T;
}

export function createTenorDraft(payload: TenorDraftRequest) {
  return requestJson<TenorDraftRecord>("/api/v1/tenor-drafts", {
    method: "POST",
    body: JSON.stringify(payload),
  });
}

export function createTenorProposals(payload: TenorProposalRequest) {
  return requestJson<TenorProposalResponse>("/api/v1/tenor-proposals", {
    method: "POST",
    body: JSON.stringify(payload),
  });
}

export function reviewTenorDraft(draftId: string, decision: TenorDecision) {
  return requestJson<TenorDraftRecord>(
    `/api/v1/tenor-drafts/${encodeURIComponent(draftId)}/review`,
    {
      method: "POST",
      body: JSON.stringify({ decision }),
    },
  );
}

export type Width = "eng" | "kerngleich" | "weit";

export type Profile = {
  profilId: string;
  schuldner: string;
  rechtsform: string;
  kanal: string[];
  url: string;
  adressat: "verbraucher" | "unternehmer" | "gemischt";
  vertragstyp: string;
  fallgruppe: string;
  verstossModus: string;
  rechtsgrundlage: string[];
  beanstandeterWortlaut: string;
  wirkung: string;
  bekannteUmgehungen: string[];
  gestaltungsmerkmale: string[];
  anlage: string;
};

export type BuildingBlock = {
  id: string;
  text: string;
  segment: string;
  fallgruppe?: string;
  verstoss_modus?: string[];
  status?: string;
  belegt_in: string[];
  position?: string;
  slots?: Record<string, string>;
};

export type ReferenceTenor = {
  id: string;
  fallgruppe: string;
  gericht_az: string;
  zitat_geprueft: boolean | string;
  freigabe_jurist: boolean;
  nicht_umfasst: Array<{
    beschreibung: string;
    begruendung: string;
    sicherheit: string;
    belegt_durch?: string;
  }>;
  kerngleich_umfasst: Array<{ beschreibung: string; begruendung: string; sicherheit: string }>;
  pruefbare_merkmale: Array<{
