  decision: TenorDecision | null;
  decided_at: string | null;
};

export type TenorProposalRequest = {
  fall_id: string;
  schuldner: string;
  fundstelle: string;
  context: string;
  fallgruppe: string;
  rechtsgrundlagen: string[];
};

export type TenorProposal = {
  strategy: "precise" | "neutral";
  title: string;
  text: string;
  source_ids: string[];
  warnings: string[];
  human_approval_required: true;
  freigabe_durch_mensch: null;
};

export type TenorProposalResponse = {
  mode: "live_openai";
  model: string;
  reference_version: string;
  proposals: [TenorProposal, TenorProposal];
};

export type TenorArchiveRequest = {
  fall_id: string;
  schuldner: string;
  title: string;
  text: string;
  context: string;
  strategy: "precise" | "neutral";
  model: string;
  reference_version: string;
  source_ids: string[];
};

export type TenorArchiveRecord = Omit<TenorArchiveRequest, "strategy"> & {
  tenor_id: string;
  created_at: string;
  source: "minimal" | "maske";
  strategy: string;
  decision: TenorDecision | null;
  decided_at: string | null;
};

export type TenorQuestionAnswerType = "yes_no" | "text" | "slider";

export type AnsweredTenorQuestion = {
  question: string;
  answer: string;
  answer_type: TenorQuestionAnswerType;
};

export type TenorSliderQuestion = {
  minimum: number;
  maximum: number;
  step: number;
  minimum_label: string;
  maximum_label: string;
  unit: string | null;
};

export type TenorQuestion = {
  question_id: string;
  text: string;
  answer_type: TenorQuestionAnswerType;
  placeholder: string | null;
  slider: TenorSliderQuestion | null;
};

export type TenorQuestionResponse = {
  mode: "live_openai";
  model: string;
  ready_to_generate: boolean;
  question: TenorQuestion | null;
};

async function requestJson<T>(url: string, init: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...init.headers,
    },
  });

  if (!response.ok) {
    let message = `HTTP ${response.status}`;
    try {
      const payload = (await response.json()) as { detail?: string | Array<{ msg?: string }> };
      if (typeof payload.detail === "string") message = payload.detail;
      else if (Array.isArray(payload.detail)) {
        message =
          payload.detail
            .map((item) => item.msg)
            .filter(Boolean)
            .join(" · ") || message;
      }
    } catch {
      // The HTTP status remains visible when the backend returns no JSON detail.
    }
    throw new Error(message);
  }

  return (await response.json()) as T;
}

export function createTenorDraft(payload: TenorDraftRequest) {
  return requestJson<TenorDraftRecord>("/api/v1/tenor-drafts", {
    method: "POST",
    body: JSON.stringify(payload),
  });
}

export function createTenorProposals(payload: TenorProposalRequest) {
  return requestJson<TenorProposalResponse>("/api/v1/tenor-proposals", {
    method: "POST",
    body: JSON.stringify(payload),
  });
}

export function createTenorQuestion(payload: {
  context: string;
  fallgruppe: string;
  answered_questions: AnsweredTenorQuestion[];
}) {
  return requestJson<TenorQuestionResponse>("/api/v1/tenor-questions", {
    method: "POST",
    body: JSON.stringify(payload),
  });
}

export function saveTenorArchiveEntry(payload: TenorArchiveRequest) {
  return requestJson<TenorArchiveRecord>("/api/v1/tenor-archive", {
    method: "POST",
    body: JSON.stringify(payload),
  });
}

export function listTenorArchiveEntries() {
  return requestJson<{ tenors: TenorArchiveRecord[] }>("/api/v1/tenor-archive", {
    method: "GET",
  });
}

export function reviewTenorDraft(draftId: string, decision: TenorDecision) {
  return requestJson<TenorDraftRecord>(
    `/api/v1/tenor-drafts/${encodeURIComponent(draftId)}/review`,
    {
      method: "POST",
      body: JSON.stringify({ decision }),
    },
  );
}

import type { AnsweredTenorQuestion, TenorQuestion } from "./tenor-api";

export type ClarificationTurn = {
  question: TenorQuestion;
  answer: string;
};

export function answeredQuestions(turns: ClarificationTurn[]): AnsweredTenorQuestion[] {
  return turns.map((turn) => ({
    question: turn.question.text,
    answer: turn.answer,
    answer_type: turn.question.answer_type,
  }));
}

export function composeClarifiedContext(context: string, turns: ClarificationTurn[]) {
  const base = context.trim();
  if (turns.length === 0) return base;
  const additions = turns
    .map((turn) => `Rückfrage: ${turn.question.text}\nAntwort: ${turn.answer}`)
    .join("\n\n");
  return `${base}\n\nErgänzende Angaben:\n${additions}`.slice(0, 4_000);
}

export function formatSliderAnswer(question: TenorQuestion, value: number) {
  const unit = question.slider?.unit?.trim();
  return unit ? `${value} ${unit}` : String(value);
}

