            step=step,
            minimum_label=minimum_label.strip(),
            maximum_label=maximum_label.strip(),
            unit=unit.strip() if isinstance(unit, str) and unit.strip() else None,
        )
    elif raw_slider is not None:
        raise TenorQuestionValidationError("Nur Slider-Rückfragen dürfen Grenzen enthalten.")
    question_id = hashlib.sha256(
        f"{context}\n{text.strip()}".encode("utf-8")
    ).hexdigest()[:16]
    return False, TenorQuestion(
        question_id=question_id,
        text=text.strip(),
        answer_type=answer_type,
        placeholder=placeholder.strip() if isinstance(placeholder, str) and placeholder.strip() else None,
        slider=slider,
